settings.css:
.dg-chat{
  --ink:#0F172A;--muted:#64748B;--line:#E2E8F0;--panel:#F8FAFC;--accent:#0F766E;--user:#1D4ED8;
  position:absolute;inset:0;display:flex;flex-direction:column;gap:10px;padding:10px 12px 12px;
  box-sizing:border-box;color:var(--ink);font-family:Roboto,"Segoe UI",Helvetica,Arial,sans-serif;
  overflow:hidden;background:#fff;
}
.dg-chat__toolbar{display:flex;align-items:center;gap:10px;flex:0 0 auto}
.dg-chat__device-label{font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.dg-chat__device{flex:1;min-width:0;height:36px;border:1px solid var(--line);border-radius:10px;padding:0 10px;background:#fff;font-size:13px;font-weight:600;color:var(--ink)}
.dg-chat__thread{flex:1 1 auto;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:10px;padding:12px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(180deg,#fff 0%,#F8FAFC 100%);scroll-behavior:smooth}
.dg-chat__empty{margin:auto;text-align:center;max-width:22rem;color:var(--muted);padding:12px 8px}
.dg-chat__empty-title{font-size:14px;font-weight:600;color:var(--ink);margin-bottom:4px}
.dg-chat__empty-text{font-size:12px;line-height:1.45}
.dg-chat__row{display:flex;gap:8px;align-items:flex-end;max-width:94%;animation:dgRise .22s ease both}
.dg-chat__row--user{align-self:flex-end;flex-direction:row-reverse}
.dg-chat__row--assistant{align-self:flex-start}
.dg-chat__avatar{flex:0 0 26px;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800}
.dg-chat__row--assistant .dg-chat__avatar{background:#ECFDF5;color:var(--accent);border:1px solid #99F6E4}
.dg-chat__row--user .dg-chat__avatar{background:#DBEAFE;color:var(--user);border:1px solid #93C5FD}
.dg-chat__bubble{padding:10px 12px;border-radius:14px;font-size:13px;line-height:1.5;white-space:pre-wrap;word-break:break-word}
.dg-chat__row--assistant .dg-chat__bubble{background:#fff;border:1px solid var(--line);border-bottom-left-radius:5px}
.dg-chat__row--user .dg-chat__bubble{background:var(--user);color:#fff;border-bottom-right-radius:5px}
.dg-chat__meta{margin-top:5px;font-size:10px;opacity:.7}
.dg-chat__bottom{flex:0 0 auto;display:flex;flex-direction:column;gap:8px}
.dg-chat__composer{display:flex;gap:8px;align-items:stretch}
.dg-chat__composer textarea{flex:1;resize:none;height:56px;min-height:56px;max-height:56px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;font-size:13px;line-height:1.4;outline:none;box-sizing:border-box;background:#fff}
.dg-chat__composer textarea:focus{border-color:#0F766E;box-shadow:0 0 0 3px rgba(15,118,110,.12)}
.dg-chat__send{min-width:88px;border:none;border-radius:12px;background:linear-gradient(180deg,#0F766E 0%,#0D9488 100%);color:#fff;font-size:13px;font-weight:700;cursor:pointer}
.dg-chat__send:disabled{opacity:.55;cursor:not-allowed}
@keyframes dgRise{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}

settings.js:
const cfg = {
  copilotBaseUrl: (window.TB_COPILOT_BASE_URL || (window.location.origin + '/copilot')),
  preferredDeviceName: '',
  storagePrefix: 'tb-operator-copilot-v1'
};

const root = container.querySelector('.dg-chat');
const deviceEl = root.querySelector('#dg-chat-device');
const messagesEl = root.querySelector('#dg-chat-messages');
const inputEl = root.querySelector('#dg-chat-input');
const sendEl = root.querySelector('#dg-chat-send');

let devices = [];
let state = { busy: false, conversationId: null, messages: [] };

function storageKey() {
  return cfg.storagePrefix + ':' + (deviceEl.value || 'none');
}

function loadState() {
  try {
    const stored = JSON.parse(localStorage.getItem(storageKey()) || '{}');
    state.conversationId = stored.conversationId || null;
    state.messages = Array.isArray(stored.messages) ? stored.messages.filter(m => m && String(m.content || '').trim()) : [];
  } catch (e) {
    state.conversationId = null;
    state.messages = [];
  }
}

function persist() {
  localStorage.setItem(storageKey(), JSON.stringify({
    conversationId: state.conversationId,
    messages: state.messages.slice(-8)
  }));
}

function authHeader() {
  const token = localStorage.getItem('jwt_token');
  return token ? { 'X-Authorization': 'Bearer ' + token } : {};
}

function setBusy(busy) {
  state.busy = busy;
  sendEl.disabled = busy;
  inputEl.disabled = busy;
  deviceEl.disabled = busy;
  sendEl.querySelector('.dg-chat__send-label').textContent = busy ? '…' : 'Send';
}

function clearThread() { messagesEl.innerHTML = ''; }

function showEmpty() {
  clearThread();
  const empty = document.createElement('div');
  empty.className = 'dg-chat__empty';
  empty.innerHTML = '<div class="dg-chat__empty-title">Operator copilot</div>' +
    '<div class="dg-chat__empty-text">Select a device, then ask about status, alarms, history, AI guidance, or procedures.</div>';
  messagesEl.appendChild(empty);
}

function appendMessage(role, text, meta) {
  const content = String(text || '').trim();
  if (!content) return;
  const empty = messagesEl.querySelector('.dg-chat__empty');
  if (empty) empty.remove();
  const row = document.createElement('div');
  row.className = 'dg-chat__row dg-chat__row--' + (role === 'USER' ? 'user' : 'assistant');
  const avatar = document.createElement('div');
  avatar.className = 'dg-chat__avatar';
  avatar.textContent = role === 'USER' ? 'OP' : 'AI';
  const bubble = document.createElement('div');
  bubble.className = 'dg-chat__bubble';
  bubble.textContent = content;
  if (meta) {
    const metaEl = document.createElement('div');
    metaEl.className = 'dg-chat__meta';
    metaEl.textContent = meta;
    bubble.appendChild(metaEl);
  }
  row.appendChild(avatar);
  row.appendChild(bubble);
  messagesEl.appendChild(row);
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

function hydrate() {
  if (!state.messages.length) { showEmpty(); return; }
  clearThread();
  state.messages.forEach(msg => appendMessage(msg.role, msg.content));
}

function remember(role, content) {
  const text = String(content || '').trim();
  if (!text) return;
  state.messages.push({ role: role, content: text });
  if (state.messages.length > 8) state.messages = state.messages.slice(-8);
  persist();
}

async function loadDevices() {
  deviceEl.innerHTML = '<option value=\"\">Loading devices…</option>';
  try {
    const res = await fetch(cfg.copilotBaseUrl + '/v1/devices', { headers: authHeader() });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    devices = await res.json();
    deviceEl.innerHTML = '';
    if (!devices.length) {
      deviceEl.innerHTML = '<option value=\"\">No accessible devices</option>';
      return;
    }
    devices.forEach(d => {
      const opt = document.createElement('option');
      opt.value = d.id;
      opt.textContent = d.name + (d.type ? (' · ' + d.type) : '');
      deviceEl.appendChild(opt);
    });
    const preferred = devices.find(d => (d.name || '').toLowerCase() === cfg.preferredDeviceName.toLowerCase());
    if (preferred) deviceEl.value = preferred.id;
    loadState();
    hydrate();
  } catch (err) {
    deviceEl.innerHTML = '<option value=\"\">Copilot unavailable</option>';
    showEmpty();
    appendMessage('ASSISTANT', 'Could not reach AI Copilot at ' + cfg.copilotBaseUrl + '. Check that the AI Copilot service/proxy is running.', 'Error');
  }
}

async function sendPrompt() {
  const text = (inputEl.value || '').trim();
  const deviceId = deviceEl.value;
  if (!text || state.busy) return;
  if (!deviceId) {
    appendMessage('ASSISTANT', 'Select a device first.');
    return;
  }
  appendMessage('USER', text, new Date().toLocaleTimeString());
  remember('USER', text);
  inputEl.value = '';
  setBusy(true);
  try {
    const res = await fetch(cfg.copilotBaseUrl + '/v1/chat', {
      method: 'POST',
      headers: Object.assign({ 'Content-Type': 'application/json' }, authHeader()),
      body: JSON.stringify({
        message: text,
        deviceId: deviceId,
        conversationId: state.conversationId,
        messages: state.messages
      })
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    state.conversationId = data.conversationId || state.conversationId;
    persist();
    appendMessage('ASSISTANT', data.answer, new Date(data.timestamp || Date.now()).toLocaleTimeString());
    remember('ASSISTANT', data.answer);
  } catch (err) {
    appendMessage('ASSISTANT', 'Chat request failed: ' + err.message, 'Error');
  } finally {
    setBusy(false);
  }
}

deviceEl.addEventListener('change', () => {
  loadState();
  hydrate();
});
sendEl.addEventListener('click', sendPrompt);
inputEl.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendPrompt();
  }
});
loadDevices();
